What does this refactoring achieve?
```javascript
// Before
function getUserData(id) {
  const user = fetchUser(id);
  const posts = fetchPosts(id);
  const comments = fetchComments(id);
  return { user, posts, comments };
}

// After
const getUserData = (id) => Promise.all([
  fetchUser(id),
  fetchPosts(id),
  fetchComments(id)
]).then(([user, posts, comments]) => ({ user, posts, comments }));
```

